<script>
const sports = <?php echo json_encode($sports, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE); ?>;

const tabs = document.querySelectorAll(".sport-tab");
const playerBg = document.getElementById("playerBg");
const playerNumber = document.getElementById("playerNumber");
const playerSport = document.getElementById("playerSport");
const playerName = document.getElementById("playerName");
const playerCountry = document.getElementById("playerCountry");
const playerQuote = document.getElementById("playerQuote");
const playerStage = document.getElementById("playerStage");
const navbar = document.getElementById("navbar");

function showSport(index) {
    const sport = sports[index];

    tabs.forEach((tab, i) => {
        tab.classList.toggle("active", i === index);
    });

    playerBg.style.backgroundImage =
        "url('" + sport.image.replace(/'/g, "\\'") + "')";

    playerNumber.textContent = sport.number + " / SPORT";
    playerSport.textContent = sport.short;
    playerName.innerHTML = sport.player
        .toUpperCase()
        .replace(" ", "<br>");
    playerCountry.textContent = sport.country.toUpperCase();
    playerQuote.textContent = sport.quote.toUpperCase();
}

let currentSport = 0;
let autoScrollTimer;

tabs.forEach(tab => {
    tab.addEventListener("click", () => {
        currentSport = Number(tab.dataset.index);
        showSport(currentSport);
        resetAutoScroll();
    });
});

function startAutoScroll() {
    autoScrollTimer = setInterval(() => {
        currentSport = (currentSport + 1) % sports.length;
        showSport(currentSport);
    }, 5000);
}

function resetAutoScroll() {
    clearInterval(autoScrollTimer);
    startAutoScroll();
}

showSport(currentSport);
startAutoScroll();

window.addEventListener("scroll", () => {
    navbar.classList.toggle("scrolled", window.scrollY > 40);
});

const revealElements = document.querySelectorAll(".reveal");

const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
        if (entry.isIntersecting) {
            entry.target.classList.add("show");
            observer.unobserve(entry.target);
        }
    });
}, { threshold: 0.12 });

revealElements.forEach(el => observer.observe(el));

playerStage.addEventListener("mousemove", (event) => {
    if (window.matchMedia("(pointer:fine)").matches) {
        const rect = playerStage.getBoundingClientRect();
        const x = (event.clientX - rect.left) / rect.width - 0.5;
        const y = (event.clientY - rect.top) / rect.height - 0.5;

        playerBg.style.transform =
            "scale(1.04) translate(" + (x * -10) + "px," + (y * -10) + "px)";
    }
});

playerStage.addEventListener("mouseleave", () => {
    playerBg.style.transform = "";
});
</script>

